    order = tuple(dict.fromkeys(preferences)) or ("days", "early", "gaps", "span")
    path = write_csv(SECTION_HEADER + "".join(
        f"{r.course},{r.section},{r.day},"
        f"{r.start // 60:02d}:{r.start % 60:02d},{r.end // 60:02d}:{r.end % 60:02d},{r.location}\n"
        for r in rows
